window.kbPageData["views/entry/k-24f809924fbb1604"] = {"key":"entry/k-24f809924fbb1604","state":{"route":"entry/k-24f809924fbb1604"},"node":{"id":"k-24f809924fbb1604","mode":"k","title":"“人工智能+”行动","type":"事实与事件","domain":"科技","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["digital","innovation"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["科技"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2025,"title":"“人工智能+”行动","slug":"f0d848f5b0f0"}],"directorySummary":"“人工智能+”行动\n2025 年 8 月 26 日，《关于深入实施“人工智能+”行动的意见》（以下简称《意见》）\n正式对外发布，这也是我国首部 AI 领域的纲领性文件，首次提出了“人工智能+”6 大行动。\n“人工智能+”6 大行动包括+科学技术、+产业发展、+消费提质、+民生福祉、+治理能\n力、+全…","sources":[{"id":"e5316b59c18f28c9","label":"“人工智能+”行动","topic":"年度政府工作","category":"时政","text":"“人工智能+”行动\n2025 年 8 月 26 日，《关于深入实施“人工智能+”行动的意见》（以下简称《意见》）\n正式对外发布，这也是我国首部 AI 领域的纲领性文件，首次提出了“人工智能+”6 大行动。\n“人工智能+”6 大行动包括+科学技术、+产业发展、+消费提质、+民生福祉、+治理能\n力、+全球合作，这 6 大重点领域面向科学家、工程师、企业员工、消费者、政府部门、全\n球伙伴等各类主体，涵盖各行各业。\n《意见》指出，到 2027 年，率先实现人工智能与 6 大重点领域广泛深度融合，新一代\n智能终端、智能体等应用普及率超 70%，智能经济核心产业规模快速增长，人工智能在公共\n治理中的作用明显增强，人工智能开放合作体系不断完善。到 2030 年，我国人工智能全面\n赋能高质量发展，新一代智能终端、智能体等应用普及率超 90%，智能经济成为我国经济发\n展的重要增长极，推动技术普惠和成果共享。到 2035 年，我国全面步入智能经济和智能社\n会发展新阶段，为基本实现社会主义现代化提供有力支撑。\n——《国务院关于深入实施“人工智能+”行动的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":7,"last":7,"page":7,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"innovation","title":"科技创新与科研组织"},{"slug":"digital","title":"数字技术与公共生活"}],"units":{"k-24f809924fbb1604":[]}};
